BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (807::BIGINT, 'Unos de los mejores estudiantes que tiene el TEC, ayuda mucho con centros, da clases extras, ayuda con la salud mental y emocional. Es el mejor de todos, 100% recomendado, no duden matricularlo con él si pueden hacerlo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2026-10-28T00:00:00+00:00'::TIMESTAMPTZ, 'd71a32242cac2be0f98d2751b2f426edcc5905f48c71a151af3c458b0a5219b1'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'El mejor profesor que la universidad puede tener, un profesor que te brinda apoyo y guia. Al profesor le importa mucho la salud emocional, el curso como tal es muy pesado pero el profesor te da el apoyo para que el curso sea posible y escucha con atención la críticas constructivas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-14T00:00:00+00:00'::TIMESTAMPTZ, 'a59ae438be9f306c583423de9542e65a8758bd7c5377a72fa94339e180377a14'::TEXT, ARRAY[630]::BIGINT[]),
    (807::BIGINT, 'El profesor explica bien, sin embargo solo revuelve de 2 a 4 problemas en toda la clase (Les dice a los estudiantes que empiecen a resolver los problemas, y pasados 20 minutos él lo comienza a resolver, sería bueno que explique más ejemplos en clase y que el estudiante los resuelva fuera de clase.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2025-05-13T00:00:00+00:00'::TIMESTAMPTZ, '7d398a54c92547762482a7b89c274ed39d7c5bed5270d38972df67e6394f4e24'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'Buen profe. Ayuda bastante para que los estudiantes puedan pasar el curso.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'a63a3e371838923c33e05c9bfcaf91a29e89b38538fcb2f65aa16c02ec0e6c12'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'El mejor profesor si quieres pasar Física, explica muy bien, se preocupa que el estudiante entienda y si ocupa ayuda, responde siempre. Siempre lleve sus dudas claras y ponga tambien de su parte.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f5e2bde154782b825b8c8da6be1e474e8b33903d309310190bcf5e188030288f'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'El profe explica de maravilla y se devuelve las veces que sea necesaria, pregúntele sin miedo. Carismático y siempre con buena actitud, no lo deje mamando cuando pregunte si entendió. Super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'ce2d92bf3b90355a40590bb7d06e7a2e7e6527d2bcf5f41ae634bc69fdbe5ced'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'Excelente profesor, se nota que le gusta enseñar y la manera en que lo hace no aburrida ni tediosa, se expresa muy bien por lo cual es facil entenderle.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-12-05T00:00:00+00:00'::TIMESTAMPTZ, '97b46e47c8cdc11c502615cd9974651a6e444efb2373495dc9a53ce7cb8a6b01'::TEXT, ARRAY[630, 604, 922]::BIGINT[]),
    (807::BIGINT, 'Es excelente como persona y como profe. Explica demasiado bien, es sumamente comprehensivo y entiende las situaciones de los estudiantes. Se pasa muy bien con él. Haber podido llevar el curso virtual con él sin tener que ir hasta San Carlos fue una bendición'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-23T00:00:00+00:00'::TIMESTAMPTZ, '891b15c6df6f59faedd917c0c0ca891fdcf9443bc347172fa6cc04a00523ef74'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'Si quieren pasar física llévenlo con él, es excelente y entiende las situaciones del estudiante, muy comprensivo y siempre atento a los estudiantes. Respeta al estudiante y siempre está dispuesto a explicar las veces que sea'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, '849240f00f36d247865ef9f599bb49803aa69cb7c8913f2a2ae16517e90ef5af'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'Explica muy clara la materia, es un profesor muy comprensivo y humano. Este profesor es excelente en cualquier curso de física que imparta. Matricular con él es la mejor opción.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-11-08T00:00:00+00:00'::TIMESTAMPTZ, '5581955eefac61055fcc3ed13818cb858338975ac039238ca5276d021168901b'::TEXT, ARRAY[922]::BIGINT[]),
    (807::BIGINT, 'Excelente profesor, lo recomiendo 1000 veces, da una excelente retroalimentación, procura que el estudiante domine el tema de la manera más sencilla, sus clases son super entendibles, además de que es un profesor muy flexible y comunicativo, nació para enseñar. Sin duda matriculen con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'd3969761d10cef35dd23c63f726a0d1f4cf73f5fe4cc95d8cf8a178b25f45458'::TEXT, ARRAY[4270]::BIGINT[]),
    (807::BIGINT, 'Un exelente ser humano y exelente profesor. Se nota en sus clases que conoce bien la materia y la sabe transmitir muy bien.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-07-29T00:00:00+00:00'::TIMESTAMPTZ, '93bf10a0281d3d17f41e7abfa92a86742822559d52ea2e319d4b121cb5c0e9cc'::TEXT, ARRAY[630, 3021]::BIGINT[]),
    (807::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'b78ce59f5cffe6c4c7daa5fbae6333c080dae608b8cc5bc36b2a78adf60fe750'::TEXT, ARRAY[630, 604, 922]::BIGINT[]),
    (807::BIGINT, 'Es un excelente profesor, Tiene un interés por las clases que se nota desde el inicio hasta el final. Ayuda bastante y se preocupa porque usted entienda. De los mejores profes que he tenido.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, '1e89b9d29b8edbecb6f833a486c4ebfea690f5d0c8c21e91be17902026ca9ecc'::TEXT, ARRAY[3021]::BIGINT[]),
    (807::BIGINT, 'Sin duda el mejor profesor que he tenido para física. NO dude matricular con él, estudie, repase y haga las clases al día y su promedio le dará alto ya que él explica genial.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'fb3ba945d22c7da321f74d7a3bb3affafbd325b6182d1d53c2ed4c8f790f903b'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, '[VIRTUAL] Súper buen profe, si pide ayuda se la va a dar. Lo único es que dura calificando entonces no hay retroalimentación tan rápida.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, '4c43c9584cf28a152aba79ef8f6aabe56c07428681aa8fbd414d292549856056'::TEXT, ARRAY[607]::BIGINT[]),
    (807::BIGINT, 'Es muy buen profesor, comprende las situaciones de los estudiantes, no regala la nota, es justo, se puede confiar el él para que aclare dudas. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2020-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'a768c7b3e390dd528d95b7a5d947ae6b08d6ef5a9bebe0c0bcafd4cc745deb1c'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'En general es muy buen profe, apoya mucho a los estudiantes y siempre está atento a cada uno de ellos, con respecto a la entrega de tareas o trabajos de catedra. Durante este semestre semestre en modalidad virtual, sí lo sentí un poco ausente, sin embargo la calidad de profesor sigue siendo la misma'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, 'b799b8a1d2bf4b80e97ab11aa9a094ca4790a9613d61c10b407f780cefdbf235'::TEXT, ARRAY[604, 630, 607, 631, 922]::BIGINT[]),
    (807::BIGINT, 'Da seguridad para consultar cualquier duda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'cce369fa85f19e8112bd129b880ef03fbe0596085cec504cffd241f7e1de95f8'::TEXT, ARRAY[604]::BIGINT[]),
    (807::BIGINT, 'No dude en matricular con él. Vacila con la clase y crea un bonito ambiente, si sos vago y no asistís a clases la puede tener en contra tuya. Las tareas de cátedra y otras asignaciones casi ni revisa, solo entreguelas. Es flexible con las entregas pero hay que hablarlo. Da mucha ayuda antes de exame'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, '85a62aa364ef430060a9aa9c21848388a9fcefd89a99f4033ab5c73aea1a484f'::TEXT, ARRAY[630, 604, 922]::BIGINT[]),
    (807::BIGINT, 'Es uno de los profesores más buenos que tiene el TEC en San Carlos. Se puede aprender muchísimo con él, y si te cuesta y muestras interés ve como puede ayudarte a que entiendas la materia mejor. Aunque las materias que da se caracterizan por ser algo aburridas, él vuelve la clase interesante.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-01-22T00:00:00+00:00'::TIMESTAMPTZ, '0f8c0dee11be4b0b24e0efe6ad043a4190fd5cfc064191769b0cc9d47b36860b'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
